package com.gymmind.ai.infrastructure.bailian;
import com.fasterxml.jackson.databind.*; import com.gymmind.ai.domain.*; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component public class BailianRerankAdapter implements RerankGateway { private final RestClient client; private final ObjectMapper mapper=new ObjectMapper(); private final String model; public BailianRerankAdapter(RestClient.Builder b){model=Optional.ofNullable(System.getenv("DASHSCOPE_RERANK_MODEL")).orElse("qwen3.7-text-rerank");client=b.baseUrl(Optional.ofNullable(System.getenv("DASHSCOPE_BASE_URL")).orElse("https://dashscope.aliyuncs.com/compatible-mode/v1")).defaultHeader("Authorization","Bearer "+Optional.ofNullable(System.getenv("DASHSCOPE_API_KEY")).orElse("")).build();} public List<RankedChunk> rerank(String query,List<ContextSegment> cs){if(query==null||query.isBlank()||cs==null||cs.isEmpty())throw new IllegalArgumentException("query and candidates required");List<String> docs=cs.stream().map(ContextSegment::text).toList();String raw=client.post().uri("/rerank").contentType(MediaType.APPLICATION_JSON).body(Map.of("model",model,"query",query,"documents",docs,"top_n",Math.min(8,docs.size()))).retrieve().body(String.class);try{List<RankedChunk> out=new ArrayList<>();for(JsonNode n:mapper.readTree(raw).path("results"))out.add(new RankedChunk(cs.get(n.path("index").asInt()).id(),n.path("index").asInt()+1));return out;}catch(Exception e){throw new IllegalStateException("invalid rerank response",e);}} }
